import type { ElementTable, RenderElement } from 'claude-code'

import { ratexColor } from './latex'
import { cells, graphemes, remember, width } from './render'
import type { Style, Theme } from './theme'
import { renderMermaidAscii, setChartSize } from './vendor/mermaid-text.js'
import { loadPele } from './vendor/pele.js'
import type { PeleArt, PelePalette } from './vendor/pelext.js'
import { drawPele } from './vendor/pelext.js'

const MAX_LINES = 80
const PAD = '\uFDD0'
const textCache = new Map<string, string | null>()
const peleCache = new Map<string, PeleArt | null>()
const palettes = new WeakMap<Theme, { palette: PelePalette; key: string }>()
let pele: ReturnType<typeof loadPele> | null = null
const renderPele = (source: string, options?: Record<string, unknown>) => (pele ??= loadPele()).render(source, options)

export const pelePalette = (theme: Theme, canvas: string): PelePalette => {
  const series = [...new Set([theme.link, theme.number, theme.heading, theme.emphasis, theme.path, theme.codeFlag, theme.accent, theme.codeString].filter((c): c is string => !!c))]
  return { canvas, text: theme.diagramText ?? theme.codeText, muted: theme.quote ?? theme.codeComment, line: theme.diagram, border: theme.diagram, accent: theme.accent, critical: theme.codeFlag, highlight: theme.emphasis ?? theme.accent, series, hues: series }
}

const paletteOf = (style: Style) => {
  const known = palettes.get(style.theme)
  if (known) return known
  const theme = Object.fromEntries(Object.entries(style.theme).map(([k, v]) => [k, v === undefined ? v : ratexColor(v)]))
  const palette = pelePalette(theme, style.canvas ?? '#1e1e2e')
  const made = { palette, key: JSON.stringify(palette) }
  palettes.set(style.theme, made)
  return made
}

export const peleText = (source: string, style: Style, columns: number): PeleArt | null => {
  if (source.length > 8000 || source.split('\n').length > MAX_LINES) return null
  const { palette, key } = paletteOf(style)
  return remember(peleCache, `${columns}:${key}:${source}`, () => drawPele(renderPele, source, palette, columns), 50)
}

const WARMUP = [
  'flowchart TD\n  A[Start] --> B{Ready?}\n  B -->|yes| C[Go]\n  B -.-> D((Wait))',
  'sequenceDiagram\n  A->>B: ask\n  B-->>A: answer',
  'classDiagram\n  class A {\n    +go() void\n  }\n  A <|-- B',
  'stateDiagram-v2\n  [*] --> A\n  A --> B: go\n  B --> [*]',
  'erDiagram\n  A ||--o{ B : has\n  A {\n    int id PK\n  }',
]

export const warmPele = (style: Style, step: number): PeleArt | null | undefined => {
  const source = WARMUP[step]
  return source === undefined ? undefined : drawPele(renderPele, source, paletteOf(style).palette, 80)
}

export const peleArt = ({ Box, Text }: ElementTable, art: PeleArt, key: string): RenderElement => (
  <Box key={key} flexDirection="column" paddingLeft={2}>
    {art.rows.map((spans, i) => (
      <Text key={`${key}.${i}`}>
        {spans.length ? spans.map((s, j) => (s.fg || s.bg || s.bold || s.inverse ? <Text key={`s${j}`} color={s.fg} backgroundColor={s.bg} bold={s.bold} inverse={s.inverse}>{s.text}</Text> : s.text)) : ' '}
